"""Derive selected normal South Continue/priority fixtures from verified North fixtures."""
from pathlib import Path
P=Path(__file__).resolve().parent;R=P.parents[1]
s=(R/'tools/run_bill_carry_source_versions_v1_validation.py').read_text(encoding='utf-8').replace('source-versions-v1','source-versions-v2').replace('source_versions_v1','source_versions_v2').replace('VERSIONS V1','VERSIONS V2')
(R/'tools/run_bill_carry_source_versions_v2_validation.py').write_text(s,encoding='utf-8')
s=(R/'tests/test_bill_carry_source_version_continue_v1.gd').read_text(encoding='utf-8')
s=s.replace('bill-carry-source-version-continue-v1','bill-carry-south-version-continue-v1').replace('BILL SOURCE VERSION CONTINUE V1:','BILL SOUTH VERSION CONTINUE V1:')
s=s.replace('for binding in [preload("res://scripts/bill_carry_player.gd").BINDING,preload("res://scripts/bill_carry_player.gd").CURRENT_BINDING]:','for binding in preload("res://scripts/bill_carry_player.gd").SOURCE_BINDINGS:')
s=s.replace('north_lane','south_lane').replace('actor.foot=finish;','actor.foot=begin;').replace('actor.path=PackedVector2Array([begin])','actor.path=PackedVector2Array([finish])')
s=s.replace('clear North contact-review lane','clear South contact-review lane').replace('player.start_motion.direction=="north"','player.start_motion.direction=="south"')
s=s.replace('("new" if binding==preload("res://scripts/bill_carry_player.gd").CURRENT_BINDING else "retained")','("new" if binding==preload("res://scripts/bill_carry_player.gd").CURRENT_BINDING else "north2-retained" if binding==preload("res://scripts/bill_carry_player.gd").NORTH2_BINDING else "north1-retained")')
s=s.replace('Actual natural sequence reaches requested interior phase','Prescribed South sequence reaches requested interior phase')
s=s.replace('Eight actual disk/fresh main restores: both source versions and gears, North first-step and arrival. Real workshop service with prescribed collision-clear North lane.', 'Twelve actual disk/fresh selected-main restores: three complete source versions, both gears, South first-step and arrival/turn-to-North. Real workshop service with prescribed collision-clear South lane.')
(R/'tests/test_bill_carry_south_version_continue_v1.gd').write_text(s,encoding='utf-8')
(R/'tests/test_bill_carry_south_version_continue_v1.gd.uid').write_text('uid://v4n4r6s8t2v5w\n',encoding='utf-8')
runner=(R/'tools/run_bill_carry_source_version_continue_v1_validation.py').read_text(encoding='utf-8').replace('bill-carry-source-version-continue-v1','bill-carry-south-version-continue-v1').replace('test_bill_carry_source_version_continue_v1','test_bill_carry_south_version_continue_v1').replace('BILL SOURCE VERSION CONTINUE V1:','BILL SOUTH VERSION CONTINUE V1:').replace('retained-bare-entry-before-room.png','north1-retained-bare-entry-before-room.png').replace('timeout=480','timeout=720')
(R/'tools/run_bill_carry_south_version_continue_v1_validation.py').write_text(runner,encoding='utf-8')
s=(R/'tests/test_bill_carry_north_version_priority_v1.gd').read_text(encoding='utf-8')
s=s.replace('bill-carry-north-version-priority-v1','bill-carry-south-version-priority-v1').replace('BILL NORTH VERSION PRIORITY V1:','BILL SOUTH VERSION PRIORITY V1:').replace('north_lane','south_lane')
s=s.replace('actor.foot=finish;','actor.foot=begin;').replace('actor.path=PackedVector2Array([begin])','actor.path=PackedVector2Array([finish])').replace('player.start_motion.direction=="north"','player.start_motion.direction=="south"')
s=s.replace('New North sources','New South sources').replace('clear North contact-review lane','clear South contact-review lane').replace('selected-main North priority','selected-main South priority')
s=s.replace('  await prepare(game,helmet)\n','  await prepare(game,helmet);await south_lane(game)\n')
s=s.replace('Natural unload returns to ordinary activity','South unload returns to ordinary activity on prescribed lane')
(R/'tests/test_bill_carry_south_version_priority_v1.gd').write_text(s,encoding='utf-8')
(R/'tests/test_bill_carry_south_version_priority_v1.gd.uid').write_text('uid://w4n4r6s8t2v5w\n',encoding='utf-8')
s=(R/'tools/run_bill_carry_north_version_priority_v1_validation.py').read_text(encoding='utf-8').replace('north-version-priority-v1','south-version-priority-v1').replace('north_version_priority_v1','south_version_priority_v1').replace('NORTH VERSION PRIORITY','SOUTH VERSION PRIORITY')
(R/'tools/run_bill_carry_south_version_priority_v1_validation.py').write_text(s,encoding='utf-8')
print('Selected South Continue/priority and source-version runners saved')
